using UnityEditor;
using UnityEditor.Events;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.UI;
namespace CatCafePreview.Editor
{
    public static class PythonDispatchLayout
    {
        static void Place(Component c,float x,float y,float w,float h){var r=c.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);}
        static void Bind(Button b,UnityEngine.Events.UnityAction action){b.onClick=new Button.ButtonClickedEvent();UnityEventTools.AddPersistentListener(b.onClick,action);b.onClick.SetPersistentListenerState(0,UnityEngine.Events.UnityEventCallState.EditorAndRuntime);}
        static void Bind(Dropdown d,UnityEngine.Events.UnityAction<int> action){d.onValueChanged=new Dropdown.DropdownEvent();UnityEventTools.AddPersistentListener(d.onValueChanged,action);d.onValueChanged.SetPersistentListenerState(0,UnityEngine.Events.UnityEventCallState.EditorAndRuntime);}
        static T Copy<T>(T source,Transform root,Transform target) where T:Component=>target.Find(AnimationUtility.CalculateTransformPath(source.transform,root)).GetComponent<T>();
        static Text Summary(Text notice){var old=notice.transform.parent.Find("Dispatch Summary");if(old!=null)Object.DestroyImmediate(old.gameObject);var text=Object.Instantiate(notice,notice.transform.parent);text.name="Dispatch Summary";text.fontSize=17;Place(text,24,110,892,60);return text;}
        static void Dropdown(Dropdown d,float x,float y,float width){Place(d,x,y,width,40);var arrow=d.transform.Find("Arrow Text");if(arrow!=null)arrow.GetComponent<RectTransform>().anchoredPosition=new Vector2(width-30,-7);}
        static void Scroll(Text text,float x,float y,float width,float height){var scroll=text.GetComponentInParent<ScrollRect>(true);Place(scroll,x,y,width,height);Place(scroll.viewport,6,6,width-30,height-12);scroll.verticalScrollbar.GetComponent<RectTransform>().sizeDelta=new Vector2(12,height-12);text.rectTransform.sizeDelta=new Vector2(width-30,text.rectTransform.sizeDelta.y);text.fontSize=17;}
        static Text MakeScroll(Text original,Text source,string name,float x){var existing=original.GetComponentInParent<ScrollRect>(true);if(existing!=null){Scroll(original,x,228,432,250);return original;}var root=source.transform.parent.parent;var clone=Object.Instantiate(root.gameObject,original.transform.parent);clone.name=name;var text=Copy(source,root,clone.transform);Object.DestroyImmediate(original.gameObject);Scroll(text,x,228,432,250);return text;}
        static void Controls(Text title,Text notice,Dropdown cats,Dropdown destinations,Dropdown returns,Button compare,Button send,Button receive,Button close){Place(title,24,16,892,40);Dropdown(cats,24,62,432);Dropdown(destinations,24,180,432);Dropdown(returns,480,180,432);Place(compare,480,62,436,40);compare.GetComponentInChildren<Text>().text="派遣先を比較する";Place(notice,24,488,892,50);notice.fontSize=14;Place(send,24,550,284,40);Place(receive,320,550,284,40);Place(close,616,550,300,40);send.GetComponentInChildren<Text>().text="選んだ猫を派遣する";receive.GetComponentInChildren<Text>().text="帰還・報酬を受け取る";close.GetComponentInChildren<Text>().text="閉じる";}
        public static void RefreshIfReady(){var p=Object.FindObjectOfType<ContentPreview>();if(p==null || p.GetComponent<PythonDispatchPanel>()?.panel==null || p.GetComponent<PythonGeneralDispatchPanel>()?.panel==null || p.GetComponent<PythonDispatchComparisonPanel>()?.panel==null)return;Build();}
        [MenuItem("Cat Cafe/開発用/UI再生成/派遣画面の整理",false,41)]
        public static void Build()
        {
            var scene=EditorSceneManager.OpenScene("Assets/Scenes/CatCafePythonState.unity");var preview=Object.FindObjectOfType<ContentPreview>();var comparison=preview.GetComponent<PythonDispatchComparisonPanel>();
            comparison.summary=Summary(comparison.notice);Place(comparison.title,24,16,892,40);Dropdown(comparison.cats,24,62,284);Dropdown(comparison.destinations,320,62,596);Scroll(comparison.details,24,190,892,288);Place(comparison.notice,24,488,892,50);comparison.notice.fontSize=14;Place(comparison.proceed,24,550,580,40);Place(comparison.close,616,550,300,40);Bind(comparison.cats,comparison.SelectCat);Bind(comparison.destinations,comparison.SelectDestination);Bind(comparison.proceed,comparison.Proceed);Bind(comparison.close,comparison.Close);
            var patron=preview.GetComponent<PythonDispatchPanel>();if(patron.cats==null){patron.cats=Object.Instantiate(patron.destinations,patron.destinations.transform.parent);patron.cats.name="Cat Selector";}if(patron.compare==null){patron.compare=Object.Instantiate(patron.close,patron.close.transform.parent);patron.compare.name="Compare Dispatch";}patron.summary=Summary(patron.notice);patron.details=MakeScroll(patron.details,comparison.details,"Destination Details",24);patron.progress=MakeScroll(patron.progress,comparison.details,"Return Details",480);Controls(patron.title,patron.notice,patron.cats,patron.destinations,patron.returns,patron.compare,patron.send,patron.receive,patron.close);Bind(patron.cats,patron.SelectCat);Bind(patron.destinations,patron.Select);Bind(patron.returns,patron.Select);Bind(patron.compare,patron.Compare);Bind(patron.send,patron.Send);Bind(patron.receive,patron.Receive);Bind(patron.close,patron.Close);
            var general=preview.GetComponent<PythonGeneralDispatchPanel>();if(general.cats==null){general.cats=Object.Instantiate(general.destinations,general.destinations.transform.parent);general.cats.name="Cat Selector";}if(general.compare==null){general.compare=Object.Instantiate(general.close,general.close.transform.parent);general.compare.name="Compare Dispatch";}general.summary=Summary(general.notice);general.details=MakeScroll(general.details,comparison.details,"Destination Details",24);general.progress=MakeScroll(general.progress,comparison.details,"Return Details",480);Controls(general.title,general.notice,general.cats,general.destinations,general.returns,general.compare,general.send,general.receive,general.close);Bind(general.cats,general.SelectCat);Bind(general.destinations,general.Select);Bind(general.returns,general.Select);Bind(general.compare,general.Compare);Bind(general.send,general.Send);Bind(general.receive,general.Receive);Bind(general.close,general.Close);
            foreach(var panel in new[]{comparison.panel,patron.panel,general.panel})panel.SetActive(false);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Debug.Log("CAT_CAFE_DISPATCH_LAYOUT_OK");
        }
    }
}
